STYLE = """
:root { color-scheme: light dark; --bg: #edf8fb; --card: #ffffff; --text: #031216; --muted: #1c5665; --rule: #c7ebf4; }
@media (prefers-color-scheme: dark) {
  :root { --bg: #031216; --card: #0e2c33; --text: #edf8fb; --muted: #8cc2d0; --rule: #1c5665; }
}
html, body { height: 100%; margin: 0; }
body { display: grid; place-items: center; background: var(--bg); color: var(--text);
  font: 17px/1.5 Geist, -apple-system, system-ui, "Segoe UI", sans-serif; }
main { box-sizing: border-box; width: min(420px, calc(100vw - 32px)); padding: 40px 36px 32px;
  background: var(--card); border: 1px solid var(--rule); border-radius: 16px; text-align: center;
  box-shadow: 0 8px 30px rgba(3, 18, 22, 0.08); }
svg { width: 150px; height: auto; margin-bottom: 20px; }
.dark { display: none; }
@media (prefers-color-scheme: dark) { .light { display: none; } .dark { display: inline; } }
h1 { font-size: 20px; font-weight: 600; margin: 0 0 8px; }
p { margin: 0; color: var(--muted); }
"""


def success_page(back_to: str = "the Ombro app") -> str:
    """The page, saying where to go back to ("the Ombro app", or "the terminal")."""
    return (
        '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n'
        '<meta name="viewport" content="width=device-width, initial-scale=1">\n'
        "<title>Signed in · Ombro</title>\n<style>"
        + STYLE
        + "</style>\n</head>\n<body>\n<main>\n"
        + LOGO_LIGHT
        + "\n"
        + LOGO_DARK
        + "\n"
        "<h1>Sign-in successful.</h1>\n"
        f"<p>You can close this tab and return to {html.escape(back_to)}.</p>\n"
        "</main>\n</body>\n</html>\n"
    )


if __name__ == "__main__":  # rewrites the app's copy: python -m ombro.signin_page
    from pathlib import Path

    Path(__file__).resolve().parents[2].joinpath("gui/src-tauri/src/signin_page.html").write_text(
        success_page(), encoding="utf-8"
    )
